List<int> dijkstra(List<List<int>> graph, int src) {
  final n = graph.length;
  final dist = List<int>.filled(n, 999999); // Large number representing infinity
  final visited = List<bool>.filled(n, false);

  dist[src] = 0;

  for (var count = 0; count < n - 1; count++) {
    final u = minDistance(dist, visited);
    visited[u] = true;

    for (var v = 0; v < n; v++) {
      if (!visited[v] &&
          graph[u][v] != 0 &&
          dist[u] != 999999 &&
          dist[u] + graph[u][v] < dist[v]) {
        dist[v] = dist[u] + graph[u][v];
      }
    }
  }

  return dist;
}

int minDistance(List<int> dist, List<bool> visited) {
  var min = 999999;
  var minIndex = -1;

  for (var v = 0; v < dist.length; v++) {
    if (!visited[v] && dist[v] <= min) {
      min = dist[v];
      minIndex = v;
    }
  }

  return minIndex;
}

