void main() {
  // Memoization cache
  final Map<int, int> _memo = {};

  // Recursive Fibonacci function with memoization
  int fib(int n) {
    if (n <= 1) return n;
    // Return cached value if present
    if (_memo.containsKey(n)) return _memo[n]!;
    // Compute and cache new value
    return _memo[n] = fib(n - 1) + fib(n - 2);
  }

  // Calculate and print first 10 Fibonacci numbers
  for (int i = 0; i < 10; i++) {
    print('fib($i) = ${fib(i)}');
  }
}

