void main() {
  // Example graph represented as an adjacency matrix
  // 0-indexed vertices with weights between nodes
  // Use a large number (9999) to represent absence of edge
  List<List<int>> graph = [
    [0, 2, 9999, 6, 9999],
    [2, 0, 3, 8, 5],
    [9999, 3, 0, 9999, 7],
    [6, 8, 9999, 0, 9],
    [9999, 5, 7, 9, 0]
  ];

  int vertices = graph.length;
  List<int> parent = List.filled(vertices, -1); // Store MST structure
  List<int> key = List.filled(vertices, 9999);   // Key values used to pick min weight edge
  List<bool> mstSet = List.filled(vertices, false); // Track vertices included in MST

  // Start with first vertex
  key[0] = 0;
  parent[0] = -1;

  // Construct MST with (vertices-1) edges
  for (int count = 0; count < vertices - 1; count++) {
    // Pick minimum key vertex not yet in MST
    int u = _minKey(key, mstSet);
    mstSet[u] = true;

    // Update key values and parent index of adjacent vertices
    for (int v = 0; v < vertices; v++) {
      if (graph[u][v] != 0 &&
          !mstSet[v] &&
          graph[u][v] < key[v]) {
        parent[v] = u;
        key[v] = graph[u][v];
      }
    }
  }

  // Print the constructed MST
  print('Edge \tWeight');
  int totalWeight = 0;
  for (int i = 1; i < vertices; i++) {
    print('${parent[i]} - $i \t${graph[i][parent[i]]}');
    totalWeight += graph[i][parent[i]];
  }
  print('Total MST weight: $totalWeight');
}

// Helper function to find vertex with minimum key value
int _minKey(List<int> key, List<bool> mstSet) {
  int min = 9999;
  int minIndex = -1;

  for (int v = 0; v < key.length; v++) {
    if (!mstSet[v] && key[v] < min) {
      min = key[v];
      minIndex = v;
    }
  }
  return minIndex;
}

