void main() {
  // Example strings to compute edit distance
  String s1 = "kitten";
  String s2 = "sitting";

  int n = s1.length;
  int m = s2.length;

  // Initialize DP table with dimensions (n+1) x (m+1)
  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(m + 1, 0));

  // Base cases: transforming to/from empty string
  for (int i = 0; i <= n; i++) {
    dp[i][0] = i; // i deletions
  }
  for (int j = 0; j <= m; j++) {
    dp[0][j] = j; // j insertions
  }

  // Fill DP table
  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      if (s1[i - 1] == s2[j - 1]) {
        // Characters match, no operation needed
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        // Take minimum of deletion, insertion, or substitution
        dp[i][j] = 1 + _min3(
          dp[i - 1][j],    // deletion
          dp[i][j - 1],    // insertion
          dp[i - 1][j - 1] // substitution
        );
      }
    }
  }

  // Result is in the bottom-right cell
  print("Edit distance between '$s1' and '$s2': ${dp[n][m]}");
}

// Helper function to compute minimum of three integers
int _min3(int a, int b, int c) {
  return a < b ? (a < c ? a : c) : (b < c ? b : c);
}

