  final coins = [1, 2, 5];
  final amount = 11;

  // Initialize DP array with a value larger than the maximum possible coins
  final dp = List<int>.filled(amount + 1, amount + 1);
  dp[0] = 0;

  // Compute minimum coins for each amount
  for (var i = 1; i <= amount; i++) {
    for (final coin in coins) {
      if (coin <= i) {
        dp[i] = dp[i] < 1 + dp[i - coin] ? dp[i] : 1 + dp[i - coin];
      }
    }
  }

  // Output the result
  final result = dp[amount] > amount ? -1 : dp[amount];
  print('Minimum coins needed: $result');
}

